import json
from src.nodes.base import BaseNode
from src.runtime.layout import get_affordance_engine

class Hou_Mcp_Affordance(BaseNode):
    name = "hou_mcp_affordance"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("asset_type",   "string", widget_type="text", default="table")
        self.add_output("affordance_json", "string")
        self.add_output("placement_mode",  "string")
        self.add_output("is_anchor",       "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        asset_type = (inputs.get("asset_type") or "").strip()
        if not asset_type:
            self.log_error("No asset_type provided.")
            return {"affordance_json": "{}", "placement_mode": "scattered", "is_anchor": False, "exec_out": True}

        try:
            eng = get_affordance_engine()
            profile = eng.get_affordances(asset_type)
            return {
                "affordance_json": json.dumps(profile.to_dict(), sort_keys=True, indent=2),
                "placement_mode":  profile.placement_mode,
                "is_anchor":       profile.is_anchor,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Affordance query failed: {exc}")
            return {"affordance_json": "{}", "placement_mode": "scattered", "is_anchor": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Affordance
